// Culinary categories: tomato, avocado and similar fruits may have culinary uses.
const normalize=s=>s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/œ/g,'oe').replace(/æ/g,'ae').toLowerCase().replace(/[^a-z0-9]/g,'');
const DICT=WORDS.map(a=>new Set(a.map(normalize)));
function assess(word,category,letter){const n=normalize(word.trim());if(!n)return {points:0,reason:'Réponse vide',eligible:false};if(!n.startsWith(normalize(letter)))return {points:0,reason:'Mauvaise initiale',eligible:false};return DICT[category].has(n)?{points:10,reason:'Mot reconnu',eligible:true}:{points:0,reason:'Absent du répertoire · à vérifier ensemble',eligible:true};}
